{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Artemisinin, the closest retrieved analogue (Morgan 0.1892), has confirmed low oral bioavailability in healthy volunteers and patients; its polycyclic lactone and neutral, poorly soluble character transfer to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Amphotericin B, a large polycyclic macrolide, shows negligible oral bioavailability in humans, supporting low F for the query's complex, highly functionalized ring system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Rosaramicin, a macrolide with a basic desosamine sugar, achieves 32±9% absolute oral bioavailability, but its ionizable amine and different scaffold limit transferability to the neutral, lactone-rich query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "Topotecan, a camptothecin with a basic amine, shows ~44% oral bioavailability, but the query lacks such an ionizable center, reducing the relevance of this high-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a complex, neutral polycyclic lactone with multiple rings and hydroxyls, most similar to artemisinin (low F) and amphotericin B (negligible F). High-F analogues are structurally dissimilar and contain ionizable basic centers absent in the query. Therefore, low oral bioavailability (F < 20%) is better supported.",
  "evidence_gaps": [
    "No direct experimental F data for the query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.2), limiting transferability.",
    "Artemisinin's low F is reported qualitatively and may not definitively fall below the 20% threshold.",
    "No data on solubility, permeability, or first-pass metabolism for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

